const O=(text,why)=>({text,why});
const ALL_QUESTIONS=[
{c:'Fundamentos',q:'¿Cuál es la definición pragmática de IA presentada en el temario?',o:[O('La ciencia que construye sistemas que piensan o actúan como humanos o racionalmente.','Esta formulación reúne los cuatro enfoques fundamentales del temario.'),O('La ciencia que fabrica exclusivamente robots humanoides.','La robótica es solo uno de los ámbitos de la IA; una IA no tiene por qué tener cuerpo.'),O('Un método para sustituir cualquier programa tradicional por una red neuronal.','La IA incluye técnicas simbólicas, búsqueda, optimización y aprendizaje; no se limita a redes neuronales.'),O('Una base de datos capaz de almacenar grandes cantidades de información.','Almacenar datos no implica razonar, aprender, percibir ni actuar de forma inteligente.')],a:0,e:'El temario organiza la IA en cuatro enfoques: pensar como humanos, pensar racionalmente, actuar como humanos y actuar racionalmente.'},
{c:'Fundamentos',q:'¿Qué comprueba principalmente el test de Turing?',o:[O('Si una máquina actúa de manera indistinguible de un humano durante una conversación escrita.','Es la finalidad del test: evaluar la conducta observable de la máquina en una conversación.'),O('Si una máquina posee consciencia real.','El test no demuestra consciencia ni explica los mecanismos internos; evalúa respuestas observables.'),O('Si una red neuronal resuelve la función XOR.','XOR se relaciona con las limitaciones del perceptrón simple, no con el test de Turing.'),O('Si un robot puede manipular objetos físicos.','La manipulación pertenece a la robótica y no es el criterio central del test conversacional.')],a:0,e:'La máquina supera la prueba si el interrogador no puede distinguir, por sus respuestas escritas, si conversa con una persona o con una máquina.'},
{c:'Fundamentos',q:'¿Qué disciplina permite a una IA comunicarse con una persona en su mismo lenguaje?',o:[O('Procesamiento del lenguaje natural.','El PLN se ocupa de comprender y producir lenguaje humano.'),O('Representación del conocimiento.','Esta disciplina almacena y estructura lo que el sistema sabe, pero no es la encargada principal de comunicarse.'),O('Robótica.','La robótica permite manipular objetos y actuar físicamente.'),O('Visión por computador.','La visión por computador procesa información visual, no el lenguaje humano.')],a:0,e:'El procesamiento del lenguaje natural proporciona las capacidades lingüísticas necesarias para entender y generar lenguaje humano.'},
{c:'Fundamentos',q:'¿Para qué sirve la representación del conocimiento en una IA?',o:[O('Para almacenar y estructurar lo que el sistema sabe o percibe.','Ese es su papel dentro de las disciplinas asociadas al test de Turing.'),O('Para mover físicamente un robot.','La actuación física corresponde a la robótica y sus actuadores.'),O('Para comprimir imágenes sin pérdida.','La compresión es una técnica informática, pero no define la representación del conocimiento.'),O('Para aumentar automáticamente la potencia de una GPU.','La potencia de cómputo es infraestructura; no es una función de representación del conocimiento.')],a:0,e:'Representar conocimiento significa codificar hechos, relaciones o reglas para que el sistema pueda utilizarlos al razonar.'},
{c:'Fundamentos',q:'¿Qué enfoque une modelos informáticos de IA con técnicas experimentales de la psicología?',o:[O('La ciencia cognitiva.','Surge para construir teorías precisas y comprobables sobre la mente combinando ambos campos.'),O('La programación genética.','Es una técnica evolutiva para generar o evolucionar programas.'),O('La lógica difusa.','Modela conceptos graduales o imprecisos, pero no es la unión de IA y psicología experimental.'),O('La optimización de redes.','Es una aplicación de IA en telecomunicaciones, no una teoría sobre la mente.')],a:0,e:'La ciencia cognitiva intenta explicar el pensamiento humano combinando modelos computacionales y evidencia psicológica.'},
{c:'Fundamentos',q:'¿Cuál es una limitación del enfoque de “pensar racionalmente” basado solo en lógica?',o:[O('Necesita conocimiento cierto y completo del mundo, algo difícil de obtener en la práctica.','La incertidumbre y la falta de reglas completas limitan el enfoque logicista.'),O('No puede representar ninguna regla formal.','La lógica sí representa reglas y relaciones con precisión cuando el dominio está bien definido.'),O('Solo funciona con imágenes y audio.','La lógica opera con símbolos y proposiciones; no está restringida a datos audiovisuales.'),O('Siempre requiere aprendizaje por refuerzo.','El razonamiento lógico puede programarse sin aprendizaje por refuerzo.')],a:0,e:'La lógica funciona bien en dominios bien definidos, pero el mundo real contiene incertidumbre y conocimiento incompleto.'},
{c:'Agentes racionales',q:'¿Qué significa que un agente actúe racionalmente?',o:[O('Que intenta maximizar su objetivo con la información y los recursos disponibles.','La racionalidad se define respecto a la meta y a la evidencia disponible.'),O('Que imita exactamente cada proceso mental humano.','Imitar la cognición humana corresponde a otro enfoque; actuar racionalmente se centra en alcanzar objetivos.'),O('Que nunca comete errores.','La incertidumbre y los límites de cálculo impiden garantizar siempre el resultado perfecto.'),O('Que utiliza únicamente reglas IF-THEN.','Los agentes también pueden usar probabilidad, aprendizaje y utilidad.')],a:0,e:'Un agente racional hace lo correcto respecto a su objetivo o busca el mejor resultado posible cuando existe incertidumbre.'},
{c:'Agentes racionales',q:'¿Por qué no siempre es posible la racionalidad perfecta?',o:[O('Porque puede no haber tiempo o capacidad para realizar todos los cálculos necesarios.','Los recursos computacionales y el tiempo son limitados en problemas reales complejos.'),O('Porque todos los entornos son completamente deterministas.','Precisamente muchos entornos reales son inciertos y cambiantes.'),O('Porque un agente racional no puede tener metas.','Las metas son esenciales para definir qué acción se considera correcta.'),O('Porque la probabilidad elimina toda incertidumbre.','La probabilidad ayuda a modelarla, pero no la elimina.')],a:0,e:'La complejidad, la incertidumbre y los límites de tiempo y cómputo obligan a buscar soluciones suficientemente buenas.'},
{c:'Tipos de IA',q:'¿Qué caracteriza a una IA débil o limitada?',o:[O('Está especializada en un dominio concreto y no transfiere por sí sola su comprensión a otros.','La especialización y la falta de generalización entre dominios definen la IA débil.'),O('Posee memoria, razonamiento espacial y comprensión general comparable a la humana.','Eso describe la aspiración de una IA general o fuerte.'),O('Carece necesariamente de utilidad práctica.','Muchas aplicaciones actuales útiles son sistemas de IA débil.'),O('Solo puede implementarse mediante sistemas expertos.','También puede usar ML, redes neuronales, búsqueda u otras técnicas.')],a:0,e:'Una IA débil puede rendir muy bien en una tarea acotada, pero no aplica automáticamente ese conocimiento a problemas distintos.'},
{c:'Tipos de IA',q:'¿Cómo puede un asistente de voz aparentar cualidades de una IA más general?',o:[O('Combinando varios sistemas especializados, como PLN, búsquedas y recomendaciones.','La integración de varias IAs débiles amplía el conjunto de capacidades.'),O('Usando un único perceptrón sin entrenamiento.','Un perceptrón simple no puede integrar por sí solo esas capacidades complejas.'),O('Eliminando todos los datos de entrenamiento.','Los componentes de aprendizaje suelen necesitar datos; eliminarlos no crea generalidad.'),O('Aplicando únicamente búsqueda en profundidad.','DFS resuelve exploración de estados, pero no cubre comprensión lingüística y recomendaciones.')],a:0,e:'La combinación de módulos especializados puede producir una experiencia amplia aunque cada módulo siga siendo una IA limitada.'},
{c:'Historia',q:'¿Qué aportaron McCulloch y Pitts en 1943?',o:[O('Un modelo matemático sencillo de redes neuronales artificiales.','Su trabajo mostró cómo redes neuronales podían calcular funciones lógicas.'),O('El término “Inteligencia Artificial”.','El término se acuñó posteriormente, en Dartmouth en 1956.'),O('El algoritmo A*.','A* pertenece a la búsqueda informada y no fue la aportación citada de estos autores.'),O('El modelo Transformer.','Los Transformers aparecieron muchas décadas después, en 2017.')],a:0,e:'En 1943 McCulloch y Pitts publicaron uno de los trabajos fundacionales sobre neuronas artificiales y funciones lógicas.'},
{c:'Historia',q:'¿Qué ocurrió en el seminario de Dartmouth de 1956?',o:[O('John McCarthy organizó el encuentro donde se acuñó el término Inteligencia Artificial.','Es el hito histórico asociado a Dartmouth en el temario.'),O('Yann LeCun presentó su reconocedor de códigos postales.','Ese sistema se sitúa en 1989.'),O('Se publicó “Attention Is All You Need”.','El artículo de los Transformers es de 2017.'),O('Se demostró por primera vez el límite de XOR del perceptrón.','La crítica matemática de los perceptrones se asocia a 1969.')],a:0,e:'Dartmouth 1956 se considera el nacimiento formal del campo y del nombre “Inteligencia Artificial”.'},
{c:'Historia',q:'¿Qué contribuyó al primer invierno de la IA?',o:[O('El fracaso de tareas ambiciosas como la traducción, junto con poco cómputo y falta de datos.','Las expectativas superaron las capacidades tecnológicas y se redujo la financiación.'),O('El exceso de GPUs y datos etiquetados.','En esa época ocurría lo contrario: faltaban potencia de cálculo y grandes datasets.'),O('El éxito comercial masivo de los sistemas expertos.','Los sistemas expertos se desarrollarían especialmente en las décadas siguientes.'),O('La aparición de los Transformers.','Los Transformers son de 2017 y pertenecen a la etapa moderna.')],a:0,e:'Las promesas no cumplidas, los límites computacionales y la complejidad de los problemas provocaron recortes y desinterés.'},
{c:'Historia',q:'¿Qué limitación del perceptrón simple se destacó en 1969?',o:[O('No podía resolver por sí solo una función XOR, que no es linealmente separable.','Un único perceptrón es un clasificador lineal y XOR exige una frontera no lineal.'),O('No podía ejecutar ninguna función lógica.','Sí puede resolver funciones linealmente separables como AND u OR.'),O('Necesitaba siempre texto etiquetado.','La limitación citada era geométrica y matemática, no específica de texto.'),O('Generaba alucinaciones lingüísticas.','Las alucinaciones se asocian a modelos generativos modernos, no al perceptrón de 1969.')],a:0,e:'El perceptrón simple solo separa datos linealmente; las redes multicapa permiten abordar relaciones no lineales como XOR.'},
{c:'Historia',q:'¿Qué caracteriza el auge de los sistemas expertos en los años 1970–1980?',o:[O('La codificación directa de conocimiento para dominios concretos.','Se buscó reducir la complejidad acotando el dominio y programando hechos y reglas.'),O('El entrenamiento de LLM con billones de tokens.','Los LLM pertenecen a una etapa mucho más reciente.'),O('La desaparición de las reglas escritas por humanos.','Los sistemas expertos clásicos dependen precisamente de reglas y conocimiento humano explícito.'),O('El uso exclusivo de aprendizaje no supervisado.','Su enfoque principal era simbólico y basado en conocimiento, no clustering.')],a:0,e:'Los sistemas expertos capturaban el saber de especialistas en dominios restringidos mediante bases de conocimiento y motores de inferencia.'},
{c:'Historia',q:'¿Cuál era la función de MYCIN?',o:[O('Diagnosticar infecciones sanguíneas y recomendar antibióticos.','Es el ejemplo médico de sistema experto citado en el temario.'),O('Inferir estructuras moleculares mediante espectrometría.','Esa era la finalidad de DENDRAL.'),O('Reconocer códigos postales manuscritos.','Esa aplicación se asocia al sistema neuronal de Yann LeCun.'),O('Generar imágenes a partir de texto.','Esa función corresponde a sistemas generativos como DALL·E.')],a:0,e:'MYCIN fue un sistema experto médico; DENDRAL, en cambio, se orientó a inferencia de estructuras moleculares.'},
{c:'Historia',q:'¿Qué avance recuperó el interés por las redes multicapa en 1986?',o:[O('La popularización de la propagación hacia atrás o backpropagation.','Permitió ajustar eficientemente los pesos de redes con varias capas.'),O('La poda alfa-beta.','Es una optimización de la búsqueda adversarial, no un método de entrenamiento neuronal.'),O('La recolección de basura.','Es una técnica de gestión de memoria relacionada históricamente con Lisp.'),O('K-means.','K-means es un algoritmo de clustering no supervisado.')],a:0,e:'La backpropagation, asociada en el temario a Hinton, Rumelhart y Williams, hizo viable entrenar redes multicapa.'},
{c:'Historia',q:'¿Qué provocó el segundo invierno de la IA alrededor de 1987?',o:[O('Promesas excesivas, límites computacionales y reglas costosas de crear y mantener.','Los sistemas no escalaron bien a problemas complejos e inciertos.'),O('La prohibición mundial de los sistemas expertos.','No hubo tal prohibición; el problema fue técnico, económico y de expectativas.'),O('La ausencia total de aplicaciones industriales.','Sí aparecieron aplicaciones, pero no cumplieron las expectativas creadas.'),O('La capacidad de resolver cualquier problema con lógica.','La lógica no logró modelar con facilidad toda la incertidumbre del mundo real.')],a:0,e:'La falta de resultados a la altura de las promesas produjo otro colapso de financiación e interés.'},
{c:'Historia',q:'¿Qué consiguió Yann LeCun en 1989 según el temario?',o:[O('Un sistema neuronal para reconocer dígitos manuscritos usado por USPS.','Fue uno de los primeros éxitos prácticos de las redes neuronales.'),O('Crear el lenguaje Lisp.','Lisp fue creado décadas antes y no por LeCun.'),O('Acuñar el término deep learning.','El hito citado es el reconocimiento de dígitos, no el nombre del campo.'),O('Diseñar AlphaGo.','AlphaGo fue desarrollado mucho después por DeepMind.')],a:0,e:'El sistema reconocía códigos postales escritos a mano y mostró una aplicación industrial real de redes neuronales.'},
{c:'Historia',q:'¿Qué hizo posible el gran impulso de la IA desde la década de 2010?',o:[O('GPUs más potentes, enormes datasets y avances en aprendizaje profundo.','La combinación de cómputo, datos y algoritmos produjo el punto de inflexión.'),O('La reducción deliberada de los datos disponibles.','Los grandes datasets, como ImageNet, fueron un factor favorable, no un obstáculo.'),O('El abandono de las redes neuronales.','Ocurrió lo contrario: las redes neuronales profundas se popularizaron.'),O('El uso exclusivo de ordenadores sin paralelismo.','Las GPUs y el procesamiento paralelo fueron claves para acelerar el entrenamiento.')],a:0,e:'La disponibilidad simultánea de grandes datos, potencia de GPU y mejores técnicas permitió entrenar modelos profundos útiles.'},
{c:'Paradigmas',q:'¿Qué pertenece al paradigma de IA simbólica y basada en conocimiento?',o:[O('Algoritmos de búsqueda y sistemas expertos.','Ambos representan o exploran conocimiento de manera explícita.'),O('Solo GAN y modelos de difusión.','Son técnicas modernas de IA generativa dentro del deep learning.'),O('Únicamente regresión y Random Forest.','Son técnicas de machine learning clásico.'),O('PSO y colonias de hormigas exclusivamente.','Se encuadran principalmente en inteligencia computacional y optimización.')],a:0,e:'El primer paradigma histórico del documento agrupa búsqueda, reglas, lógica y sistemas expertos.'},
{c:'Paradigmas',q:'¿Cuál fue el cambio esencial del paradigma Bottom-Up de machine learning?',o:[O('Pasar de programar reglas a alimentar datos para que el modelo extraiga patrones.','Es el cambio central desde conocimiento explícito hacia aprendizaje estadístico.'),O('Sustituir todos los datos por reglas IF-THEN.','Eso describe el enfoque simbólico Top-Down.'),O('Evitar por completo la estadística.','El ML clásico se apoya fuertemente en estimación estadística.'),O('Representar siempre el problema como un árbol de búsqueda.','Los árboles pueden usarse, pero el ML no exige representar todo como espacio de estados.')],a:0,e:'En ML no se codifica manualmente cada regla de decisión: el algoritmo aprende relaciones a partir de ejemplos.'},
{c:'Heurísticas',q:'¿Qué es una heurística en IA?',o:[O('Una regla práctica o estimación que guía la búsqueda hacia una solución razonable.','Reduce la exploración aprovechando conocimiento aproximado del problema.'),O('Una demostración que garantiza siempre el óptimo con coste cero.','Las heurísticas suelen intercambiar garantía de optimalidad por eficiencia.'),O('Un conjunto de datos obligatoriamente etiquetado.','Eso describe datos de aprendizaje supervisado, no una heurística.'),O('Una capa física de una GPU.','Una heurística es conocimiento o estimación algorítmica, no hardware.')],a:0,e:'La heurística orienta al algoritmo para evitar explorar todas las posibilidades y obtener una buena solución en tiempo razonable.'},
{c:'Heurísticas',q:'¿Cuál es el dilema principal de una heurística?',o:[O('Puede sacrificar la garantía de optimalidad a cambio de eficiencia computacional.','Ese intercambio permite tratar espacios de búsqueda enormes.'),O('Siempre consume más memoria que la fuerza bruta.','Su finalidad suele ser reducir trabajo; el consumo concreto depende del algoritmo.'),O('Solo puede utilizarse en medicina.','Las heurísticas aparecen en búsqueda, sistemas expertos y optimización, entre otros ámbitos.'),O('Impide usar conocimiento del dominio.','Precisamente suele codificar conocimiento útil del dominio.')],a:0,e:'Las heurísticas aceleran la resolución, pero una guía aproximada no siempre conduce a la solución matemáticamente óptima.'},
{c:'Sistemas expertos',q:'¿Cuáles son los dos componentes centrales de un sistema experto clásico?',o:[O('Base de conocimiento y motor de inferencia.','La primera contiene hechos y reglas; el segundo las aplica para razonar.'),O('GPU y cámara.','Son componentes posibles de un robot, no la estructura lógica de un sistema experto.'),O('Dataset sin etiquetar y K-means.','Eso corresponde a un escenario de aprendizaje no supervisado.'),O('Generador y discriminador.','Es la estructura característica de una GAN.')],a:0,e:'La base de conocimiento almacena reglas IF-THEN y hechos; el motor de inferencia decide cómo aplicarlos.'},
{c:'Sistemas expertos',q:'¿Qué hace un sistema basado en reglas Top-Down?',o:[O('Ejecuta conocimiento escrito explícitamente por expertos humanos.','El sistema aplica reglas programadas y no descubre por sí solo reglas nuevas.'),O('Aprende siempre patrones a partir de datos masivos sin reglas.','Eso describe un enfoque Bottom-Up de machine learning.'),O('Genera imágenes mediante difusión.','Los modelos de difusión pertenecen a la IA generativa.'),O('Agrupa datos mediante K-means.','K-means descubre grupos en datos sin etiquetar.')],a:0,e:'En el enfoque Top-Down el conocimiento humano se representa explícitamente, por ejemplo con reglas “SI... ENTONCES...”.'},
{c:'Machine Learning',q:'¿Qué necesita el aprendizaje supervisado?',o:[O('Datos etiquetados con pares de entrada y salida esperada.','Las etiquetas proporcionan la respuesta objetivo que el modelo debe aprender.'),O('Solo datos sin ninguna respuesta conocida.','Ese es el escenario típico del aprendizaje no supervisado.'),O('Un entorno y recompensas, sin dataset estático.','Eso caracteriza al aprendizaje por refuerzo.'),O('Reglas lógicas escritas siempre a mano.','El aprendizaje supervisado extrae una relación desde ejemplos etiquetados.')],a:0,e:'El modelo supervisado compara sus predicciones con etiquetas conocidas para ajustar sus parámetros.'},
{c:'Machine Learning',q:'¿Qué diferencia una clasificación de una regresión?',o:[O('La clasificación predice categorías; la regresión, valores numéricos continuos.','Es la distinción principal entre ambos tipos de tareas supervisadas.'),O('La clasificación no usa datos y la regresión sí.','Ambas pueden entrenarse con datos etiquetados.'),O('La regresión solo produce verdadero o falso.','Una salida binaria es clasificación; la regresión estima cantidades continuas.'),O('La clasificación siempre es no supervisada.','La clasificación habitual del temario es una tarea supervisada.')],a:0,e:'“Spam/no spam” es clasificación; predecir el precio de una vivienda es regresión.'},
{c:'Machine Learning',q:'¿Qué hace el aprendizaje no supervisado?',o:[O('Busca estructuras, relaciones o grupos en datos sin etiquetar.','No recibe respuestas correctas predefinidas y explora la organización interna de los datos.'),O('Aprende exclusivamente mediante premios y castigos.','Eso corresponde al aprendizaje por refuerzo.'),O('Predice siempre una etiqueta conocida durante el entrenamiento.','Eso sería aprendizaje supervisado.'),O('Copia reglas de una base de conocimiento.','Eso describe un sistema simbólico basado en reglas.')],a:0,e:'El aprendizaje no supervisado incluye clustering, reducción de dimensionalidad y asociación.'},
{c:'Machine Learning',q:'¿Qué algoritmo se cita como ejemplo típico de clustering?',o:[O('K-means.','K-means divide observaciones sin etiquetar en grupos según su similitud.'),O('A*.','A* es búsqueda informada en espacios de estados.'),O('Minimax.','Minimax se utiliza en decisiones entre adversarios.'),O('Backpropagation.','Backpropagation ajusta pesos en redes neuronales; no es un algoritmo de clustering.')],a:0,e:'K-means agrupa datos similares alrededor de centroides y es un ejemplo clásico de aprendizaje no supervisado.'},
{c:'Machine Learning',q:'¿Cómo funciona el aprendizaje por refuerzo?',o:[O('Un agente interactúa con un entorno y aprende mediante recompensas y castigos.','Busca una política de acciones que maximice la recompensa acumulada.'),O('El modelo recibe todas las respuestas correctas en una tabla estática.','Eso encaja con aprendizaje supervisado, no con interacción y recompensa.'),O('Un experto escribe todas las reglas IF-THEN.','Eso es un sistema basado en conocimiento.'),O('El algoritmo solo agrupa elementos similares.','Agrupar sin etiquetas es clustering no supervisado.')],a:0,e:'El aprendizaje por refuerzo usa ensayo y error: las consecuencias de cada acción orientan el comportamiento futuro del agente.'},
{c:'Machine Learning',q:'¿Qué combina el aprendizaje semisupervisado?',o:[O('Una pequeña cantidad de datos etiquetados y muchos datos sin etiquetar.','Aprovecha ambos conjuntos cuando etiquetar a gran escala es costoso.'),O('Solo reglas lógicas y ninguna muestra.','Eso no constituye aprendizaje semisupervisado.'),O('Dos datasets completamente etiquetados.','La característica distintiva es usar también un gran volumen sin etiquetas.'),O('Únicamente recompensas negativas.','Las recompensas pertenecen al aprendizaje por refuerzo.')],a:0,e:'Los pocos ejemplos etiquetados orientan la tarea y los no etiquetados ayudan a capturar la estructura general de los datos.'},
{c:'Machine Learning',q:'¿En qué consiste el aprendizaje por transferencia?',o:[O('Reutilizar los pesos de un modelo preentrenado y ajustarlo a una tarea relacionada.','Transfiere conocimiento del dominio origen al destino mediante fine-tuning.'),O('Entrenar siempre desde cero con parámetros aleatorios.','Es justamente lo que el transfer learning intenta evitar.'),O('Copiar literalmente las salidas del modelo sin adaptarlo.','Se reutiliza conocimiento interno y normalmente se ajustan capas o pesos.'),O('Convertir un algoritmo BFS en DFS.','Eso cambia una estrategia de búsqueda, no transfiere conocimiento aprendido.')],a:0,e:'El transfer learning reduce datos, tiempo y coste al partir de características ya aprendidas por un modelo grande.'},
{c:'Machine Learning',q:'En el caso de YOLO preentrenado, ¿qué suelen haber aprendido las primeras capas?',o:[O('Características visuales generales como bordes, curvas y texturas.','Estas características universales pueden reutilizarse en nuevas tareas visuales.'),O('Únicamente el nombre textual de cada nueva especie local.','Ese conocimiento específico se aprende al ajustar las capas finales con datos del nuevo dominio.'),O('Reglas de inferencia de un sistema experto médico.','YOLO es un modelo de visión, no una base de reglas médicas.'),O('La ruta óptima de cualquier ciudad.','La planificación de rutas no es lo aprendido por sus primeras capas visuales.')],a:0,e:'Las capas tempranas capturan patrones visuales básicos; las finales se especializan en las clases del problema concreto.'},
{c:'Machine Learning',q:'¿Cuál es la fase de fine-tuning de un LLM?',o:[O('Adaptar un modelo base preentrenado con un conjunto menor y especializado.','El ajuste fino especializa la comprensión general adquirida durante el preentrenamiento.'),O('Borrar todos los pesos aprendidos y comenzar desde cero.','Eso eliminaría precisamente el conocimiento que se quiere transferir.'),O('Limitarse a escribir un prompt, sin modificar el modelo.','El prompting guía la inferencia, pero no es necesariamente fine-tuning.'),O('Aplicar búsqueda binaria al vocabulario.','La búsqueda binaria no define el ajuste fino de un modelo de lenguaje.')],a:0,e:'SFT, LoRA o QLoRA son técnicas citadas para adaptar un modelo general a ámbitos como medicina, derecho o código empresarial.'},
{c:'Machine Learning',q:'¿Cuál es el primer paso del flujo básico de un proyecto de machine learning?',o:[O('Recolectar y comprender los datos.','Sin entender los datos no se pueden preparar ni elegir adecuadamente el modelo.'),O('Publicar el modelo antes de entrenarlo.','El despliegue llega después de preparar, entrenar y evaluar.'),O('Reservar todos los datos para prueba.','Se necesitan datos de entrenamiento y datos independientes de prueba.'),O('Elegir siempre una red neuronal profunda.','El algoritmo depende del problema y de los datos disponibles.')],a:0,e:'El proceso comienza por conocer las fuentes, variables, calidad y significado de los datos.'},
{c:'Machine Learning',q:'¿Por qué no debe probarse un modelo con los mismos datos usados para entrenarlo?',o:[O('Porque no mediría bien su capacidad para generalizar a casos nuevos.','El modelo podría memorizar patrones del entrenamiento y ofrecer una evaluación engañosa.'),O('Porque los datos de entrenamiento desaparecen automáticamente.','Los datos no desaparecen; se separan para evitar una evaluación sesgada.'),O('Porque solo pueden evaluarse sistemas expertos.','Cualquier modelo predictivo debe evaluarse con datos no vistos.'),O('Porque R-cuadrado exige imágenes.','R-cuadrado se usa en regresión y no exige datos visuales.')],a:0,e:'El temario propone como práctica habitual reservar aproximadamente un 20 % para prueba y un 80 % para entrenamiento.'},
{c:'Redes neuronales',q:'¿Qué representa un perceptrón?',o:[O('La unidad lógica básica análoga a una neurona artificial.','Recibe entradas, las transforma mediante pesos/criterios y produce una salida.'),O('Una población completa de un algoritmo genético.','Una población está formada por individuos candidatos, no por perceptrones.'),O('Una regla de clustering.','El perceptrón es un modelo neuronal lineal, no una regla de agrupamiento.'),O('Un motor de inferencia experto.','El motor aplica reglas simbólicas; el perceptrón calcula una salida a partir de entradas.')],a:0,e:'El perceptrón es la unidad elemental de una ANN y se inspira de forma limitada en el funcionamiento de una neurona biológica.'},
{c:'Redes neuronales',q:'¿Por qué se combinan múltiples perceptrones en una red?',o:[O('Para modelar relaciones y fronteras no lineales que uno solo no puede resolver.','Las capas de unidades permiten componer transformaciones más complejas.'),O('Para convertir cualquier problema en una base de reglas manual.','Las redes aprenden parámetros; no exigen convertir todo a reglas IF-THEN.'),O('Para garantizar siempre el óptimo global.','Una red multicapa es más expresiva, pero el entrenamiento no garantiza siempre el óptimo global.'),O('Para eliminar la necesidad de datos.','Las redes necesitan datos u otra señal de aprendizaje para ajustar sus parámetros.')],a:0,e:'Un perceptrón simple es lineal; una red multicapa puede abordar problemas no linealmente separables.'},
{c:'Deep Learning',q:'¿Cuál es la jerarquía correcta?',o:[O('Machine Learning ⊃ Redes neuronales ⊃ Deep Learning.','Deep learning es la parte que utiliza redes de múltiples capas/arquitecturas profundas.'),O('Deep Learning ⊃ IA ⊃ algoritmos.','La IA es el campo más amplio; deep learning es un subconjunto.'),O('Sistemas expertos ⊃ Machine Learning ⊃ BFS.','Los sistemas expertos y el ML son enfoques distintos, y BFS es búsqueda.'),O('IA generativa ⊃ toda la informática.','La IA generativa es un subconjunto especializado, no el conjunto de la informática.')],a:0,e:'Dentro de la IA, el ML incluye redes neuronales; las arquitecturas profundas forman el deep learning.'},
{c:'Deep Learning',q:'¿Para qué tipo de datos destaca especialmente el deep learning?',o:[O('Datos no estructurados como imágenes, audio y texto.','Las redes profundas aprenden representaciones jerárquicas sin depender tanto de características manuales.'),O('Solo tablas de dos columnas perfectamente lineales.','Esos casos pueden resolverse con modelos mucho más simples.'),O('Únicamente reglas jurídicas ya formalizadas.','Las reglas explícitas encajan más directamente en sistemas simbólicos.'),O('Solo árboles de búsqueda sin observaciones.','Deep learning se entrena a partir de datos o señales de interacción.')],a:0,e:'CNN, RNN/LSTM y Transformers se desarrollaron para extraer patrones complejos en datos perceptivos o secuenciales.'},
{c:'Búsqueda',q:'¿Qué explora un algoritmo de búsqueda en IA?',o:[O('Un espacio de estados desde una situación inicial hasta una meta.','Los estados y transiciones suelen representarse con árboles o grafos.'),O('Solo un dataset etiquetado para regresión.','Eso pertenece al aprendizaje supervisado.'),O('Únicamente los pesos de una red neuronal.','Los pesos se optimizan durante el entrenamiento; no son el espacio de estados típico descrito.'),O('Una base de datos sin objetivo.','La búsqueda se define por estado inicial, acciones y meta, entre otros elementos.')],a:0,e:'Los algoritmos de búsqueda evalúan secuencias de acciones y estados futuros para hallar un camino hacia el objetivo.'},
{c:'Búsqueda',q:'¿Qué caracteriza a la búsqueda no informada?',o:[O('No dispone de contexto adicional aparte de la representación del problema.','Explora sin una estimación heurística sobre qué estado parece más prometedor.'),O('Siempre conoce la distancia exacta a la meta.','Eso sería información adicional propia de una búsqueda informada.'),O('Utiliza obligatoriamente redes neuronales.','BFS y DFS pueden operar sin aprendizaje ni redes.'),O('Solo puede resolver juegos de dos jugadores.','La búsqueda no informada se aplica a muchos espacios de estados, no solo juegos adversariales.')],a:0,e:'BFS y DFS son ejemplos de búsqueda ciega o no informada.'},
{c:'Búsqueda',q:'¿Cómo recorre el espacio la búsqueda en anchura (BFS)?',o:[O('Explora todos los nodos de una profundidad antes de pasar a la siguiente.','BFS avanza por niveles desde el estado inicial.'),O('Sigue una rama hasta el fondo antes de retroceder.','Eso describe DFS.'),O('Elige siempre el nodo de menor heurística.','Eso se parece a una búsqueda voraz informada.'),O('Genera descendientes mediante cruce y mutación.','Ese es el mecanismo de los algoritmos genéticos.')],a:0,e:'BFS revisa primero los estados más cercanos en número de pasos, nivel por nivel.'},
{c:'Búsqueda',q:'¿Cómo recorre el espacio la búsqueda en profundidad (DFS)?',o:[O('Sigue una rama tan profundamente como puede y luego retrocede.','DFS prioriza profundizar antes de explorar alternativas del mismo nivel.'),O('Explora simultáneamente todos los nodos de cada nivel.','Eso describe BFS.'),O('Necesita siempre una función heurística admisible.','DFS es una búsqueda no informada y no exige heurística.'),O('Selecciona individuos por fitness.','La selección por aptitud pertenece a algoritmos evolutivos.')],a:0,e:'DFS profundiza por un camino; si no alcanza la meta, hace backtracking y prueba otra rama.'},
{c:'Búsqueda',q:'¿Qué distingue a la búsqueda informada?',o:[O('Utiliza conocimiento del dominio, normalmente expresado mediante heurísticas.','La información adicional guía qué estados explorar primero.'),O('No conoce absolutamente nada del problema.','Eso sería búsqueda no informada.'),O('Nunca utiliza árboles ni grafos.','También explora espacios representados mediante árboles o grafos.'),O('Solo funciona con datos etiquetados.','Las etiquetas no son un requisito de los algoritmos de búsqueda informada.')],a:0,e:'Una heurística estima la calidad, coste o cercanía de un estado respecto a la meta.'},
{c:'Búsqueda',q:'¿Cuál es el algoritmo más popular citado para búsqueda informada?',o:[O('A* (A estrella).','Combina el coste acumulado con una estimación heurística hacia la meta.'),O('K-means.','K-means es clustering.'),O('Backpropagation.','Backpropagation entrena redes neuronales.'),O('QLoRA.','QLoRA es una técnica eficiente de ajuste fino.')],a:0,e:'El temario presenta la búsqueda voraz y A*, destacando A* como una de las técnicas informadas más útiles.'},
{c:'Búsqueda',q:'¿Qué combinación se usa en búsqueda entre adversarios?',o:[O('Minimax y poda alfa-beta.','Minimax modela las decisiones rivales y alfa-beta evita explorar ramas irrelevantes.'),O('BFS y K-means.','BFS es búsqueda ciega y K-means clustering; no forman la pareja adversarial clásica.'),O('Regresión lineal y SVM.','Son modelos supervisados, no algoritmos de juego adversarial.'),O('LoRA y cuantización.','Son optimizaciones de modelos neuronales, no búsqueda entre jugadores.')],a:0,e:'Esta búsqueda se aplica a entornos donde otros agentes cambian el estado, como juegos de dos jugadores.'},
{c:'Optimización',q:'¿En qué se inspiran los algoritmos evolutivos?',o:[O('En la evolución biológica y la selección natural.','Usan poblaciones, reproducción, selección y mutación como analogías computacionales.'),O('En la lógica aristotélica exclusivamente.','La lógica formal pertenece al paradigma simbólico.'),O('En el test de Turing.','El test evalúa comportamiento conversacional, no optimización.'),O('En la búsqueda binaria.','La búsqueda binaria divide un conjunto ordenado y no simula evolución.')],a:0,e:'Los algoritmos evolutivos generan variantes y favorecen las soluciones con mejor aptitud a lo largo de generaciones.'},
{c:'Optimización',q:'¿Qué garantiza un algoritmo genético?',o:[O('Busca una solución buena, pero no garantiza que sea la mejor posible.','Es una metaheurística adecuada para espacios grandes, con compromiso entre calidad y tiempo.'),O('Encuentra siempre el óptimo exacto en tiempo constante.','No existe esa garantía general, especialmente en problemas combinatorios difíciles.'),O('Produce siempre la misma población aunque cambie la semilla.','La inicialización, selección y mutación suelen incorporar aleatoriedad.'),O('Solo resuelve funciones lineales.','Puede aplicarse a problemas complejos, discretos o continuos.')],a:0,e:'Los algoritmos genéticos suelen converger a soluciones de alta calidad sin demostrar necesariamente la optimalidad global.'},
{c:'Optimización',q:'¿Qué mide la función de aptitud o fitness?',o:[O('La calidad de cada solución candidata.','Su puntuación guía la selección de progenitores y supervivientes.'),O('El número de etiquetas de un dataset.','No mide el tamaño del conjunto, sino el rendimiento del individuo.'),O('La capacidad de una persona para pasar el test de Turing.','Fitness es un criterio de optimización dentro del algoritmo evolutivo.'),O('La profundidad fija de BFS.','BFS no selecciona individuos por aptitud.')],a:0,e:'La función fitness traduce el objetivo del problema a una puntuación comparable entre individuos.'},
{c:'Optimización',q:'¿Qué sucede durante el cruce y la mutación?',o:[O('Se combina información de progenitores y se introducen pequeños cambios en la descendencia.','Ambos operadores crean variedad y exploran nuevas soluciones.'),O('Se etiquetan manualmente todas las muestras.','Eso es preparación de datos supervisados.'),O('Se eliminan siempre los mejores individuos.','Normalmente se favorecen individuos aptos, aunque se conserva diversidad.'),O('Se aplica una regla IF-THEN sin crear variantes.','Eso corresponde a inferencia simbólica, no reproducción evolutiva.')],a:0,e:'El cruce recombina material de soluciones existentes y la mutación introduce diversidad para evitar estancamiento.'},
{c:'Optimización',q:'¿Cuál es un ejemplo de inteligencia de enjambre?',o:[O('Optimización por colonias de hormigas.','Simula cómo interacciones simples colectivas producen búsqueda inteligente.'),O('Regresión logística.','Es un modelo supervisado de clasificación.'),O('DENDRAL.','Es un sistema experto basado en conocimiento.'),O('Búsqueda binaria.','Es un algoritmo determinista sobre colecciones ordenadas.')],a:0,e:'Las colonias de hormigas y los enjambres de partículas son ejemplos de swarm intelligence.'},
{c:'IA generativa',q:'¿Qué cambio conceptual introduce la IA generativa frente a la discriminativa?',o:[O('Pasa de clasificar o predecir a sintetizar contenido nuevo.','Puede generar texto, código, imágenes, audio o vídeo.'),O('Deja de usar por completo redes neuronales.','La GenAI actual se apoya fuertemente en deep learning.'),O('Sustituye todos los modelos por reglas manuales.','Eso sería regresar al enfoque simbólico clásico.'),O('Solo agrupa datos sin etiquetas.','El clustering no define la creación generativa de contenido.')],a:0,e:'La IA discriminativa separa o estima clases/valores; la generativa aprende distribuciones para producir nuevas muestras plausibles.'},
{c:'IA generativa',q:'¿Qué arquitectura de 2017 impulsó los LLM modernos?',o:[O('Transformer, presentado en “Attention Is All You Need”.','Su mecanismo de atención permitió modelar contextos amplios de forma eficaz.'),O('Perceptrón simple.','Es una unidad lineal mucho más antigua e insuficiente para un LLM moderno.'),O('Árbol de decisión manual.','No es la arquitectura central de los grandes modelos de lenguaje.'),O('Minimax.','Se usa en juegos adversariales, no para entrenar LLM.')],a:0,e:'Los Transformers son la base de familias como GPT, BERT, Llama y otros modelos de lenguaje.'},
{c:'IA generativa',q:'¿Qué es una alucinación de un LLM?',o:[O('Una respuesta inventada o incorrecta presentada de forma convincente.','El modelo genera texto plausible, que no siempre coincide con hechos verdaderos.'),O('Una imagen vista por un robot mediante Lidar.','Eso sería percepción sensorial, no una alucinación lingüística.'),O('Un fallo físico de la GPU que siempre apaga el sistema.','Puede haber fallos de hardware, pero no definen la alucinación de un LLM.'),O('Una etiqueta correcta del dataset.','Una etiqueta verificada es evidencia de entrenamiento, no contenido fabricado.')],a:0,e:'Los LLM optimizan plausibilidad lingüística y pueden afirmar datos falsos con seguridad aparente; por eso hay que verificar.'},
{c:'IA generativa',q:'¿Por qué un mismo prompt puede producir resultados distintos?',o:[O('Porque la generación suele muestrear probabilísticamente entre varias continuaciones posibles.','La aleatoriedad controlada hace que no siempre se elija el mismo token o resultado.'),O('Porque el prompt se elimina antes de procesarse.','El prompt condiciona la generación; no se descarta.'),O('Porque todos los modelos usan reglas deterministas idénticas.','Si fueran completamente deterministas y con igual estado, la salida se repetiría.'),O('Porque la búsqueda BFS reordena las palabras.','La variabilidad generativa no se explica por BFS.')],a:0,e:'El modelo asigna probabilidades a posibles salidas y los parámetros de muestreo pueden introducir variación.'},
{c:'IA generativa',q:'¿Qué tres factores explican el salto reciente de la IA generativa?',o:[O('Grandes datos, cómputo de alto rendimiento y mejores algoritmos.','Móviles/IoT aportaron datos, GPUs/cloud aportaron cómputo y Transformers mejoraron el modelado.'),O('Menos datos, CPU más lenta y reglas fijas.','Esos factores limitarían el entrenamiento de modelos grandes.'),O('Solo una mejora en pantallas y baterías.','Pueden ayudar a productos finales, pero no explican el salto algorítmico principal.'),O('La eliminación del aprendizaje automático.','La IA generativa moderna deriva del deep learning.')],a:0,e:'Datos, infraestructura y algoritmos avanzaron conjuntamente hasta hacer viables los modelos generativos a gran escala.'},
{c:'Aplicaciones',q:'¿Cómo ayuda la IA a detectar fraude bancario?',o:[O('Identifica transacciones que se alejan de los patrones habituales de gasto.','Las anomalías pueden señalar operaciones sospechosas en tiempo real.'),O('Elimina todas las transacciones electrónicas.','Eso impediría el servicio; la IA busca diferenciar actividad legítima de anómala.'),O('Aplica solo reglas de ajedrez.','Las reglas de ajedrez no modelan el comportamiento financiero.'),O('Genera contraseñas para cada compra sin analizar datos.','La detección descrita se basa en patrones de transacción y comportamiento.')],a:0,e:'El análisis de grandes históricos permite reconocer comportamientos inusuales y limitar operaciones potencialmente fraudulentas.'},
{c:'Aplicaciones',q:'¿Cómo puede aplicarse la IA frente a un ataque DDoS?',o:[O('Identificando y redirigiendo peticiones maliciosas para reducir el impacto.','El sistema distingue tráfico legítimo de patrones anómalos de saturación.'),O('Aumentando sin límite todas las peticiones recibidas.','Eso agravaría la sobrecarga del servicio.'),O('Publicando los datos sensibles del servidor.','Expondría información y empeoraría la seguridad.'),O('Desactivando permanentemente Internet para usuarios legítimos.','La meta es mantener el servicio y filtrar el tráfico malicioso.')],a:0,e:'La IA aprende patrones de usuarios, sistemas y red para detectar tráfico no legítimo y activar medidas defensivas.'},
{c:'Aplicaciones',q:'¿Qué problema clásico se relaciona con la optimización logística de rutas?',o:[O('El problema del viajante de comercio.','Busca un recorrido de coste mínimo para visitar distintas ubicaciones.'),O('La puerta XOR.','XOR ilustra una limitación del perceptrón lineal.'),O('El test de Turing.','Evalúa comportamiento conversacional humano.'),O('La recolección de basura.','Gestiona memoria, no rutas de reparto.')],a:0,e:'La logística real amplía el viajante con tráfico, plazos, tipos de carretera, vehículos y carga.'},
{c:'Interacción empresarial',q:'¿Cuál es el ciclo iterativo propuesto para integrar IA en decisiones de negocio?',o:[O('Sentir, analizar y reaccionar.','Primero se obtienen datos, luego se analizan y finalmente se ejecutan acciones.'),O('Mutar, cruzar y compilar.','Los dos primeros son operadores evolutivos y no forman el ciclo empresarial descrito.'),O('Preguntar, ocultar y borrar.','No corresponde a la taxonomía del temario.'),O('Entrenar, publicar y olvidar.','Los sistemas necesitan medición, reacción e iteración continua.')],a:0,e:'La organización recoge señales, obtiene información con análisis y actúa; los resultados alimentan una nueva iteración.'},
{c:'Interacción empresarial',q:'¿Qué es un sistema de apoyo a la toma de decisiones?',o:[O('Una IA que ayuda a empleados o directivos a elegir mejores acciones.','Apoya al humano con análisis o recomendaciones, sin exigir autonomía total.'),O('Un sistema que prohíbe cualquier intervención humana.','El apoyo a decisiones mantiene al humano como decisor.'),O('Una aplicación destinada solo a crear imágenes artísticas.','Puede haber generación visual, pero no define este tipo de sistema empresarial.'),O('Un algoritmo que únicamente ordena números.','Puede usar muchas técnicas para aportar información útil al decisor.')],a:0,e:'Estos sistemas transforman datos en recomendaciones para decisiones estratégicas o tareas cotidianas.'},
{c:'Ética',q:'¿Qué principio ético exige poder explicar cómo funciona un sistema y quién responde si falla?',o:[O('Responsabilidad y transparencia.','Busca trazabilidad, explicabilidad y asignación clara de responsabilidades.'),O('Clustering y asociación.','Son técnicas de ML, no principios éticos.'),O('Mutación y selección.','Son operadores evolutivos.'),O('Compresión y cifrado.','Son técnicas informáticas; el principio preguntado es gobernanza responsable.')],a:0,e:'La transparencia ayuda a comprender decisiones y la responsabilidad determina quién debe responder por consecuencias negativas.'},
{c:'Ética',q:'¿Qué problema aparece cuando los datos representan mucho mejor a unos grupos que a otros?',o:[O('Sesgo e inequidad.','El modelo puede favorecer o perjudicar sistemáticamente a determinados colectivos.'),O('Optimalidad garantizada.','Un dataset desequilibrado no garantiza calidad ni justicia.'),O('Transfer learning perfecto.','Transferir pesos no elimina por sí solo sesgos de los datos.'),O('Búsqueda ciega.','El problema descrito es de representación y trato desigual, no de exploración sin heurística.')],a:0,e:'Datos parciales o históricos pueden reproducir discriminaciones por género, raza, edad u otras características.'},
{c:'Ética',q:'¿Qué principio se centra en mantener seguros los datos personales y usarlos con consentimiento?',o:[O('Privacidad y seguridad.','Protege la confidencialidad y limita el uso a finalidades aceptadas.'),O('Autonomía del algoritmo sobre las personas.','La ética busca que las personas conserven control, no que el algoritmo lo monopolice.'),O('Supervivencia del más apto.','Es una metáfora evolutiva, no una norma de protección de datos.'),O('Explosión combinatoria.','Es un problema computacional de espacios de búsqueda.')],a:0,e:'La información personal debe protegerse y tratarse de acuerdo con permisos, finalidad y medidas de seguridad adecuadas.'},
{c:'Ética',q:'¿Qué implica el principio de autonomía y control?',o:[O('Que las personas mantengan control significativo sobre lo que hacen los sistemas de IA.','La tecnología debe ajustarse a necesidades humanas y permitir supervisión.'),O('Que la IA pueda ignorar siempre las instrucciones humanas.','Eso eliminaría el control y podría aumentar riesgos.'),O('Que ningún sistema pueda automatizar tarea alguna.','La autonomía humana no prohíbe automatizar; exige gobernanza y límites apropiados.'),O('Que todos los modelos sean sistemas expertos.','El principio se aplica a cualquier técnica de IA.')],a:0,e:'La IA debe permanecer bajo supervisión y no anular injustificadamente la capacidad de elección de las personas.'},
{c:'Visión integradora',q:'¿Cuál de estas afirmaciones refleja mejor el estado actual de la IA?',o:[O('Los sistemas modernos combinan técnicas; una tecnología anterior no queda automáticamente obsoleta.','AlphaGo, por ejemplo, integra redes neuronales y búsqueda MCTS.'),O('La IA generativa ha reemplazado por completo búsqueda y optimización.','Los modelos modernos siguen dependiendo de optimización y pueden integrarse con búsqueda.'),O('Todos los problemas deben resolverse con el mismo algoritmo maestro.','El temario recalca que no existe un algoritmo universal para cualquier problema.'),O('La IA simbólica y el ML nunca pueden combinarse.','Los enfoques híbridos son posibles y frecuentes.')],a:0,e:'La evolución de la IA es acumulativa: técnicas simbólicas, búsqueda, optimización y aprendizaje pueden cooperar en un mismo sistema.'}
];
// Banco equilibrado de 60 preguntas: se excluyen 8 cuestiones redundantes del material ampliado.
const OMITTED=new Set([3,8,9,24,31,37,42,52]);
const BANK=ALL_QUESTIONS.filter((_,index)=>!OMITTED.has(index));
const $=s=>document.querySelector(s);
const els={setup:$('#setup-screen'),quiz:$('#quiz-screen'),result:$('#result-screen'),form:$('#setup-form'),category:$('#question-category'),title:$('#question-title'),options:$('#options'),feedback:$('#feedback'),next:$('#next-button'),quit:$('#quit-button'),progressLabel:$('#progress-label'),liveScore:$('#live-score'),progressBar:$('#progress-bar'),progressTrack:$('.progress-track'),grade:$('#grade'),ring:$('#grade-ring'),correct:$('#correct-stat'),wrong:$('#wrong-stat'),points:$('#points-stat'),message:$('#result-message'),retry:$('#retry-button'),mistakes:$('#mistakes-button'),review:$('#mistakes-review'),mistakesList:$('#mistakes-list'),mistakesCount:$('#mistakes-count'),dialog:$('#quit-dialog'),confirmQuit:$('#confirm-quit')};
let state={questions:[],index:0,correct:0,wrong:0,penalty:.33,answered:false,mistakes:[]};

function shuffle(array){const copy=[...array];for(let i=copy.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[copy[i],copy[j]]=[copy[j],copy[i]]}return copy}
function show(screen){[els.setup,els.quiz,els.result].forEach(x=>x.hidden=x!==screen);window.scrollTo({top:0,behavior:'smooth'})}
function startQuiz(count,penalty,source=BANK){
  state={questions:shuffle(source).slice(0,Math.min(count,source.length)),index:0,correct:0,wrong:0,penalty,answered:false,mistakes:[]};
  show(els.quiz);renderQuestion();
}
function renderQuestion(){
  state.answered=false;els.feedback.hidden=true;els.feedback.className='feedback';els.next.hidden=true;
  const item=state.questions[state.index];
  item.display=shuffle(item.o.map((option,index)=>({...option,original:index})));
  els.category.textContent=item.c;els.title.textContent=item.q;els.options.innerHTML='';
  item.display.forEach((option,index)=>{
    const button=document.createElement('button');button.type='button';button.className='option';button.dataset.original=option.original;
    button.innerHTML=`<span class="option-key">${index+1}</span><span class="option-text"></span><span class="option-icon" aria-hidden="true"></span>`;
    button.querySelector('.option-text').textContent=option.text;button.addEventListener('click',()=>answer(button,option.original));els.options.append(button);
  });
  updateProgress();setTimeout(()=>els.options.querySelector('.option')?.focus(),80);
}
function answer(selected,chosen){
  if(state.answered)return;state.answered=true;const item=state.questions[state.index];const isCorrect=chosen===item.a;const buttons=[...els.options.querySelectorAll('.option')];
  buttons.forEach(btn=>{btn.disabled=true;const original=Number(btn.dataset.original);if(original===item.a){btn.classList.add('correct');btn.querySelector('.option-icon').textContent='✓'}else if(btn===selected){btn.classList.add('incorrect');btn.querySelector('.option-icon').textContent='×'}else btn.classList.add('dimmed')});
  if(isCorrect){state.correct++;els.feedback.classList.add('correct');els.feedback.innerHTML=`<strong>Correcta</strong><p>${item.e}</p>`}
  else{state.wrong++;state.mistakes.push({item,chosen});els.feedback.classList.add('incorrect');const chosenOption=item.o[chosen];const right=item.o[item.a];els.feedback.innerHTML='<strong>Incorrecta</strong>';const p=document.createElement('p');p.textContent=`Tu opción no es correcta porque ${lowerFirst(chosenOption.why)} La respuesta correcta es «${right.text}»: ${lowerFirst(item.e)}`;els.feedback.append(p)}
  els.feedback.hidden=false;els.next.hidden=false;updateProgress();els.feedback.scrollIntoView({behavior:'smooth',block:'nearest'});setTimeout(()=>els.next.focus(),120);
}
function lowerFirst(text){return text.charAt(0).toLowerCase()+text.slice(1)}
function updateProgress(){
  const total=state.questions.length;const completed=state.index+(state.answered?1:0);const percent=total?completed/total*100:0;
  els.progressLabel.textContent=`Pregunta ${Math.min(state.index+1,total)} de ${total}`;els.liveScore.textContent=`${state.correct} aciertos · ${state.wrong} fallos`;
  els.progressBar.style.width=`${percent}%`;els.progressTrack.setAttribute('aria-valuenow',String(Math.round(percent)));
}
function nextQuestion(){if(!state.answered)return;if(state.index<state.questions.length-1){state.index++;renderQuestion()}else finish()}
function finish(){
  const total=state.questions.length;const net=state.correct-(state.wrong*state.penalty);const grade=Math.max(0,net/total*10);show(els.result);
  els.grade.textContent=grade.toLocaleString('es-ES',{minimumFractionDigits:1,maximumFractionDigits:1});els.ring.style.setProperty('--grade-deg',`${grade/10*360}deg`);
  els.correct.textContent=state.correct;els.wrong.textContent=state.wrong;els.points.textContent=net.toLocaleString('es-ES',{maximumFractionDigits:2});
  els.message.textContent=grade>=8?'Muy buen dominio del temario. Repasa los pocos fallos para afianzarlo.':grade>=5?'Vas por buen camino. Revisa tus fallos y haz otro intento para ganar seguridad.':'Conviene hacer un repaso dirigido de los fallos antes de repetir el simulacro.';
  els.mistakes.disabled=state.mistakes.length===0;els.mistakes.textContent=state.mistakes.length?'Repasar fallos':'Sin fallos';els.review.hidden=true;renderMistakes();
}
function renderMistakes(){
  els.mistakesList.innerHTML='';els.mistakesCount.textContent=`${state.mistakes.length} ${state.mistakes.length===1?'fallo':'fallos'}`;
  state.mistakes.forEach(({item,chosen},i)=>{const card=document.createElement('article');card.className='mistake-card';const h=document.createElement('h3');h.textContent=`${i+1}. ${item.q}`;const wrong=document.createElement('p');wrong.className='answer-wrong';wrong.innerHTML='<strong>Tu respuesta:</strong> ';wrong.append(document.createTextNode(item.o[chosen].text));const right=document.createElement('p');right.className='answer-right';right.innerHTML='<strong>Respuesta correcta:</strong> ';right.append(document.createTextNode(item.o[item.a].text));const why=document.createElement('p');why.textContent=item.e;card.append(h,wrong,right,why);els.mistakesList.append(card)});
}
els.form.addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.currentTarget);startQuiz(Number(data.get('question-count')),Number(data.get('penalty')))});
els.next.addEventListener('click',nextQuestion);els.quit.addEventListener('click',()=>els.dialog.showModal());els.confirmQuit.addEventListener('click',()=>show(els.setup));els.retry.addEventListener('click',()=>show(els.setup));els.mistakes.addEventListener('click',()=>{els.review.hidden=!els.review.hidden;if(!els.review.hidden)els.review.scrollIntoView({behavior:'smooth'})});
document.addEventListener('keydown',e=>{if(els.quiz.hidden)return;if(!state.answered&&['1','2','3','4'].includes(e.key)){els.options.querySelectorAll('.option')[Number(e.key)-1]?.click()}else if(state.answered&&(e.key==='Enter'||e.key==='ArrowRight'))nextQuestion()});
(function(){const t=$('[data-theme-toggle]'),r=document.documentElement;let theme=matchMedia('(prefers-color-scheme:dark)').matches?'dark':'light';const icon=()=>{r.setAttribute('data-theme',theme);t.setAttribute('aria-label',theme==='dark'?'Activar modo claro':'Activar modo oscuro');t.innerHTML=theme==='dark'?'<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><circle cx="12" cy="12" r="5"/><path d="M12 1v2M12 21v2M4.22 4.22l1.42 1.42M18.36 18.36l1.42 1.42M1 12h2M21 12h2M4.22 19.78l1.42-1.42M18.36 5.64l1.42-1.42"/></svg>':'<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79Z"/></svg>'};icon();t.addEventListener('click',()=>{theme=theme==='dark'?'light':'dark';icon()})})();
